set-query-parameter.value:
@{
                        // Get title and escape single quotes for OData query
                        var title = context.Request.OriginalUrl.Query.GetValueOrDefault("title", "")
                            .Replace("'", "''")
                            .Replace("%27", "''");
                        return $"(Title eq '{title}')";
					}

outbound.set-body:
@{
			var response = context.Response.Body.As();
			var movies = new List();

			foreach (JObject movie in response["value"] ?? new JArray())
			{
				movies.Add(new
				{
					id = (string)movie["RowKey"],
					title = (string)movie["Title"],
					year = (int)movie["Year"]
				});
			}

			return JsonConvert.SerializeObject(movies);
		}
